+            var oPar2 = heavyParOf(mOff);
+            if ((oEl2 === "H" || oEl2 === "h") && oPar2 >= 0) {
+              var aA0 = Math.atan2(atoms[mOff].y - atoms[oPar2].y, atoms[mOff].x - atoms[oPar2].x);
+              var aB0 = gaps[0].a;
